-- Generated by samesight from samesight.policy.ts. Do not edit: change the policy and
-- run `samesight generate`, which writes a new migration when this output changes.

create schema if not exists samesight;
grant usage on schema samesight to authenticated;

-- Claim helpers -------------------------------------------------------------------------

create or replace function samesight.tenant_id()
returns uuid
language sql
stable
set search_path = ''
as $$
  select nullif(auth.jwt() ->> 'tenant_id', '')::uuid
$$;

create or replace function samesight.app_role()
returns text
language sql
stable
set search_path = ''
as $$
  select nullif(auth.jwt() ->> 'app_role', '')
$$;

revoke execute on function samesight.tenant_id(), samesight.app_role() from public, anon;
grant execute on function samesight.tenant_id(), samesight.app_role() to authenticated;

-- Custom access token hook --------------------------------------------------------------
-- Adds tenant_id and app_role as top-level claims, read from "members". Enable it in
-- supabase/config.toml locally, and under Authentication > Hooks on a hosted project.

create or replace function samesight.custom_access_token_hook(event jsonb)
returns jsonb
language plpgsql
stable
set search_path = ''
as $$
declare
  claims jsonb := coalesce(event -> 'claims', '{}'::jsonb);
  member record;
begin
  select m.org_id as tenant, m.role::text as role
    into member
    from public.members m
   where m.user_id = (event ->> 'user_id')::uuid;

  if found then
    claims := jsonb_set(claims, '{tenant_id}', to_jsonb(member.tenant::text));
    claims := jsonb_set(claims, '{app_role}', to_jsonb(member.role));
  else
    -- No membership: no tenant, so every policy and stream returns nothing.
    claims := claims - 'tenant_id' - 'app_role';
  end if;

  return jsonb_set(event, '{claims}', claims);
end;
$$;

grant usage on schema samesight to supabase_auth_admin;
grant execute on function samesight.custom_access_token_hook(jsonb) to supabase_auth_admin;
revoke execute on function samesight.custom_access_token_hook(jsonb) from public, anon, authenticated;
grant select on table public.members to supabase_auth_admin;

-- Table privileges ----------------------------------------------------------------------
-- anon gets nothing. authenticated gets only what a policy below allows: INSERT and UPDATE
-- on the columns a client may set, never server-owned ones.

revoke all on public.organizations, public.members, public.project_members, public.projects, public.tasks from anon, authenticated;
grant select on public.organizations, public.members, public.project_members, public.projects, public.tasks to authenticated;
grant insert (id, org_id, project_id, user_id) on public.project_members to authenticated;
grant delete on public.project_members to authenticated;
grant insert (id, org_id, name) on public.projects to authenticated;
grant update (name) on public.projects to authenticated;
grant delete on public.projects to authenticated;
grant insert (id, org_id, project_id, title, status, assignee_id, created_by) on public.tasks to authenticated;
grant update (title, status, assignee_id) on public.tasks to authenticated;
grant delete on public.tasks to authenticated;

-- Row level security --------------------------------------------------------------------
-- Every policy on these tables is dropped first, so the policy file is the whole truth.

alter table public.organizations enable row level security;
alter table public.members enable row level security;
alter table public.project_members enable row level security;
alter table public.projects enable row level security;
alter table public.tasks enable row level security;

do $$
declare
  p record;
begin
  for p in
    select policyname, tablename from pg_policies
     where schemaname = 'public' and tablename in ('organizations', 'members', 'project_members', 'projects', 'tasks')
  loop
    execute format('drop policy %I on public.%I', p.policyname, p.tablename);
  end loop;
end;
$$;

drop policy if exists "members: auth hook reads" on public.members;
create policy "members: auth hook reads" on public.members
  as permissive for select to supabase_auth_admin
  using (true);
comment on policy "members: auth hook reads" on public.members is 'samesight';

create policy "organizations: read" on public.organizations
  for select to authenticated
  using (
    id = (select samesight.tenant_id())
    and (select samesight.app_role()) in ('owner', 'member')
  );
comment on policy "organizations: read" on public.organizations is 'samesight';

create policy "members: read" on public.members
  for select to authenticated
  using (
    org_id = (select samesight.tenant_id())
    and (
      (select samesight.app_role()) = 'owner'
      or ((select samesight.app_role()) = 'member' and user_id = (select auth.uid()))
    )
  );
comment on policy "members: read" on public.members is 'samesight';

create policy "project_members: read" on public.project_members
  for select to authenticated
  using (
    org_id = (select samesight.tenant_id())
    and (
      (select samesight.app_role()) = 'owner'
      or ((select samesight.app_role()) = 'member' and user_id = (select auth.uid()))
    )
  );
comment on policy "project_members: read" on public.project_members is 'samesight';

create policy "project_members: insert" on public.project_members
  for insert to authenticated
  with check (
    org_id = (select samesight.tenant_id())
    and (select samesight.app_role()) = 'owner'
  );
comment on policy "project_members: insert" on public.project_members is 'samesight';

create policy "project_members: update" on public.project_members
  for update to authenticated
  using (
    org_id = (select samesight.tenant_id())
    and (select samesight.app_role()) = 'owner'
  )
  with check (
    org_id = (select samesight.tenant_id())
    and (select samesight.app_role()) = 'owner'
  );
comment on policy "project_members: update" on public.project_members is 'samesight';

create policy "project_members: delete" on public.project_members
  for delete to authenticated
  using (
    org_id = (select samesight.tenant_id())
    and (select samesight.app_role()) = 'owner'
  );
comment on policy "project_members: delete" on public.project_members is 'samesight';

create policy "projects: read" on public.projects
  for select to authenticated
  using (
    org_id = (select samesight.tenant_id())
    and (
      (select samesight.app_role()) = 'owner'
      or ((select samesight.app_role()) = 'member' and id in (select p.project_id from public.project_members p where p.user_id = (select auth.uid())))
    )
  );
comment on policy "projects: read" on public.projects is 'samesight';

create policy "projects: insert" on public.projects
  for insert to authenticated
  with check (
    org_id = (select samesight.tenant_id())
    and (select samesight.app_role()) = 'owner'
  );
comment on policy "projects: insert" on public.projects is 'samesight';

create policy "projects: update" on public.projects
  for update to authenticated
  using (
    org_id = (select samesight.tenant_id())
    and (select samesight.app_role()) = 'owner'
  )
  with check (
    org_id = (select samesight.tenant_id())
    and (select samesight.app_role()) = 'owner'
  );
comment on policy "projects: update" on public.projects is 'samesight';

create policy "projects: delete" on public.projects
  for delete to authenticated
  using (
    org_id = (select samesight.tenant_id())
    and (select samesight.app_role()) = 'owner'
  );
comment on policy "projects: delete" on public.projects is 'samesight';

create policy "tasks: read" on public.tasks
  for select to authenticated
  using (
    org_id = (select samesight.tenant_id())
    and (
      (select samesight.app_role()) = 'owner'
      or ((select samesight.app_role()) = 'member' and project_id in (select p.project_id from public.project_members p where p.user_id = (select auth.uid())))
    )
  );
comment on policy "tasks: read" on public.tasks is 'samesight';

create policy "tasks: insert" on public.tasks
  for insert to authenticated
  with check (
    org_id = (select samesight.tenant_id())
    and (
      (select samesight.app_role()) = 'owner'
      or ((select samesight.app_role()) = 'member' and project_id in (select p.project_id from public.project_members p where p.user_id = (select auth.uid())))
    )
    and created_by = (select auth.uid())
  );
comment on policy "tasks: insert" on public.tasks is 'samesight';

create policy "tasks: update" on public.tasks
  for update to authenticated
  using (
    org_id = (select samesight.tenant_id())
    and (
      (select samesight.app_role()) = 'owner'
      or ((select samesight.app_role()) = 'member' and assignee_id = (select auth.uid()) and project_id in (select p.project_id from public.project_members p where p.user_id = (select auth.uid())))
    )
  )
  with check (
    org_id = (select samesight.tenant_id())
    and (
      (select samesight.app_role()) = 'owner'
      or ((select samesight.app_role()) = 'member' and assignee_id = (select auth.uid()) and project_id in (select p.project_id from public.project_members p where p.user_id = (select auth.uid())))
    )
  );
comment on policy "tasks: update" on public.tasks is 'samesight';

create policy "tasks: delete" on public.tasks
  for delete to authenticated
  using (
    org_id = (select samesight.tenant_id())
    and (select samesight.app_role()) = 'owner'
  );
comment on policy "tasks: delete" on public.tasks is 'samesight';

-- Tables that left the policy -----------------------------------------------------------
-- A table that still carries a policy this generator made (marked by its comment) but is no
-- longer in the policy is closed: those policies, client grants and our triggers are dropped,
-- and RLS stays on, so nothing reads or writes it until a policy covers it again. Policies
-- written by hand are left alone.

do $$
declare
  t record;
  pol record;
begin
  for t in
    select distinct c.relname as name
      from pg_policy p
      join pg_class c on c.oid = p.polrelid
      join pg_namespace n on n.oid = c.relnamespace
      join pg_description d on d.objoid = p.oid and d.classoid = 'pg_policy'::regclass
     where n.nspname = 'public' and d.description = 'samesight'
       and c.relname not in ('organizations', 'members', 'project_members', 'projects', 'tasks')
  loop
    for pol in
      select p.polname from pg_policy p
        join pg_description d on d.objoid = p.oid and d.classoid = 'pg_policy'::regclass
       where p.polrelid = format('public.%I', t.name)::regclass and d.description = 'samesight'
    loop
      execute format('drop policy %I on public.%I', pol.polname, t.name);
    end loop;
    execute format('revoke all on public.%I from anon, authenticated', t.name);
    if exists (select from pg_roles where rolname = 'powersync_role') then
      execute format('revoke all on public.%I from powersync_role', t.name);
    end if;
    execute format('grant update, delete, truncate on public.%I to service_role', t.name);
    execute format('drop trigger if exists %I on public.%I', t.name || '_touch', t.name);
    execute format('drop trigger if exists %I on public.%I', t.name || '_append_only', t.name);
    execute format('drop trigger if exists %I on public.%I', t.name || '_no_truncate', t.name);
  end loop;
end;
$$;

-- Triggers ------------------------------------------------------------------------------
-- Dropped on every table first, so a table that loses touch or append-only loses its trigger.

drop trigger if exists organizations_touch on public.organizations;
drop trigger if exists organizations_append_only on public.organizations;
drop trigger if exists organizations_no_truncate on public.organizations;
drop trigger if exists members_touch on public.members;
drop trigger if exists members_append_only on public.members;
drop trigger if exists members_no_truncate on public.members;
drop trigger if exists project_members_touch on public.project_members;
drop trigger if exists project_members_append_only on public.project_members;
drop trigger if exists project_members_no_truncate on public.project_members;
drop trigger if exists projects_touch on public.projects;
drop trigger if exists projects_append_only on public.projects;
drop trigger if exists projects_no_truncate on public.projects;
drop trigger if exists tasks_touch on public.tasks;
drop trigger if exists tasks_append_only on public.tasks;
drop trigger if exists tasks_no_truncate on public.tasks;
grant update, delete, truncate on public.organizations, public.members, public.project_members, public.projects, public.tasks to service_role;

-- Server-owned timestamps ---------------------------------------------------------------

create or replace function samesight.touch()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  new := jsonb_populate_record(new, jsonb_build_object(tg_argv[0], now()));
  return new;
end;
$$;

revoke execute on function samesight.touch() from public, anon, authenticated;

create trigger tasks_touch
  before update on public.tasks
  for each row execute function samesight.touch('updated_at');

-- Replication ---------------------------------------------------------------------------
-- PowerSync reads the WAL through a role with BYPASSRLS, so the sync config is the only
-- filter between these tables and a device. A REPLICATION role can also decode every table
-- regardless of the publication, so the service and this role's password are trusted with
-- the whole database. The role has no login here; its password is set out of band.

do $$
begin
  if not exists (select from pg_roles where rolname = 'powersync_role') then
    create role powersync_role with replication bypassrls nologin;
  end if;
end;
$$;

grant usage on schema public to powersync_role;
grant select on public.organizations, public.members, public.project_members, public.projects, public.tasks to powersync_role;

alter table public.organizations replica identity full;
alter table public.members replica identity full;
alter table public.project_members replica identity full;
alter table public.projects replica identity full;
alter table public.tasks replica identity full;

-- Altered in place when it exists, so a running replication slot keeps its publication.
do $$
begin
  if exists (select from pg_publication where pubname = 'powersync') then
    alter publication powersync set table public.organizations, public.members, public.project_members, public.projects, public.tasks;
  else
    create publication powersync for table public.organizations, public.members, public.project_members, public.projects, public.tasks;
  end if;
end;
$$;

-- Write path: apply_batch ---------------------------------------------------------------
-- One call per PowerSync transaction, so it commits or fails as a unit. SECURITY INVOKER:
-- every statement runs as the caller, so RLS and the column grants check each row exactly
-- as for a direct REST call. Each op is {op, table, id, data}:
--   - a table outside the allowlist below, or an unknown op, raises SS001 (held, not dropped);
--   - PUT reads only the insert columns from data (a PUT carries the whole local row, so
--     server-owned columns are dropped); the tenant comes from the token, and a row stored
--     under another tenant is refused; a row that exists already (a replay, or a second
--     PUT) must be readable, and is then updated with the update columns where the caller
--     may update it (last write wins) and otherwise left as it is, so a replayed insert by a
--     role that cannot update the row succeeds instead of being refused;
--   - PATCH carries only changed columns, so a key outside the update list is refused;
--     zero rows affected (missing, or hidden by RLS) raises;
--   - DELETE is refused on append-only tables; a row gone or hidden is a replay (no-op), a
--     visible row RLS will not delete raises.
-- Refusals raise P0001, which the connector treats as permanent. A token without a tenant
-- raises 28000, so the connector refreshes it. Identifiers come only from the allowlist and
-- are quoted with format('%I'); payload values reach SQL only as a bound jsonb parameter.

create or replace function public.apply_batch(ops jsonb)
returns void
language plpgsql
security invoker
set search_path = ''
as $$
declare
  -- insert: columns a client may set on create. update: columns a client may change.
  spec constant jsonb := '{
    "project_members": {"appendOnly": false, "tenant": "org_id", "insert": ["project_id", "user_id"],
                       "update": []},
    "projects": {"appendOnly": false, "tenant": "org_id", "insert": ["name"],
                "update": ["name"]},
    "tasks": {"appendOnly": false, "tenant": "org_id", "insert": ["project_id", "title", "status", "assignee_id"],
             "update": ["title", "status", "assignee_id"]}
  }';
  tenant uuid := (select samesight.tenant_id());
  op jsonb;
  kind text;
  tbl text;
  t jsonb;
  row_id uuid;
  data jsonb;
  tenant_col text;
  cols text[];
  upd text[];
  record_json jsonb;
  col_list text;
  affected bigint;
  found_row boolean;
begin
  if jsonb_typeof(ops) is distinct from 'array' then
    raise exception 'apply_batch: ops must be a JSON array' using errcode = 'SS001';
  end if;
  if tenant is null then
    raise exception 'apply_batch: the token carries no tenant' using errcode = '28000';
  end if;

  for op in select value from jsonb_array_elements(ops) loop
    kind := op ->> 'op';
    tbl := op ->> 'table';
    t := spec -> tbl;
    if t is null then
      raise exception 'apply_batch: table % is not writable', coalesce(tbl, '(none)') using errcode = 'SS001';
    end if;
    -- Before the shape checks, so an op this server does not know is held, not refused.
    if kind is null or kind not in ('PUT', 'PATCH', 'DELETE') then
      raise exception 'apply_batch: unknown op %', coalesce(kind, '(none)') using errcode = 'SS001';
    end if;
    if op ->> 'id' is null then
      raise exception 'apply_batch: % op on % has no id', kind, tbl;
    end if;
    row_id := (op ->> 'id')::uuid;
    data := coalesce(op -> 'data', '{}'::jsonb);
    if jsonb_typeof(data) is distinct from 'object' then
      raise exception 'apply_batch: data for % % must be an object', tbl, row_id;
    end if;
    tenant_col := t ->> 'tenant';

    if kind = 'PUT' then
      cols := array(
        select c from jsonb_array_elements_text(t -> 'insert') c where data ? c
      ) || array['id', tenant_col];
      upd := array(
        select c from jsonb_array_elements_text(t -> 'update') c where data ? c
      );
      -- A row stored under another tenant: a write queued before this user moved to the
      -- current tenant. Refused rather than re-homed into the new tenant.
      if data ->> tenant_col is not null and not samesight.is_tenant(data ->> tenant_col, tenant) then
        raise exception 'apply_batch: % % belongs to another tenant', tbl, row_id;
      end if;
      -- jsonb_populate_record parses every key it is given, so drop the others first: a
      -- malformed server-owned value must not fail the write it is ignored by.
      record_json := (
        select coalesce(jsonb_object_agg(key, value), '{}'::jsonb) from jsonb_each(data) where key = any(cols)
      ) || jsonb_build_object('id', row_id, tenant_col, tenant);
      col_list := (select string_agg(format('%I', c), ', ') from unnest(cols) c);
      -- Not ON CONFLICT DO UPDATE: that puts the existing row through the caller's UPDATE
      -- policy and raises when it fails, so a role that may insert but not update this row
      -- could never replay its own insert.
      execute format(
        'insert into public.%I (%s) select %s from jsonb_populate_record(null::public.%I, $1) on conflict (id) do nothing',
        tbl, col_list, col_list, tbl
      ) using record_json;
      get diagnostics affected = row_count;
      if affected = 0 then
        -- A replay finds its own row. Finding none (or one this caller cannot read)
        -- means the id belongs to someone else's row.
        execute format('select exists (select 1 from public.%I where id = $1)', tbl)
          into found_row using row_id;
        if not found_row then
          raise exception 'apply_batch: % % conflicts with a row you cannot write', tbl, row_id;
        end if;
        -- Last write wins where the caller may update the row. RLS skips a row its UPDATE
        -- policy does not allow (the replay is then a no-op, and the server's copy syncs
        -- back), and still raises on a WITH CHECK violation.
        if not (t ->> 'appendOnly')::boolean and cardinality(upd) > 0 then
          col_list := (select string_agg(format('%I', c), ', ') from unnest(upd) c);
          execute format(
            'update public.%I as t set (%s) = (select %s from jsonb_populate_record(null::public.%I, $1)) where t.id = $2',
            tbl, col_list, col_list, tbl
          ) using (select jsonb_object_agg(key, value) from jsonb_each(data) where key = any(upd)), row_id;
        end if;
      end if;

    elsif kind = 'PATCH' then
      if (t ->> 'appendOnly')::boolean then
        raise exception 'apply_batch: % is append-only; add a new row instead', tbl;
      end if;
      if exists (select 1 from jsonb_object_keys(data) k where not (t -> 'update') ? k) then
        raise exception 'apply_batch: % % changes a column clients may not change', tbl, row_id;
      end if;
      upd := array(select k from jsonb_object_keys(data) k);
      if cardinality(upd) = 0 then
        execute format('select exists (select 1 from public.%I where id = $1)', tbl)
          into found_row using row_id;
        if not found_row then
          raise exception 'apply_batch: % % not found or not writable', tbl, row_id;
        end if;
        continue;
      end if;
      col_list := (select string_agg(format('%I', c), ', ') from unnest(upd) c);
      execute format(
        'update public.%I as t set (%s) = (select %s from jsonb_populate_record(null::public.%I, $1)) where t.id = $2',
        tbl, col_list, col_list, tbl
      ) using data, row_id;
      get diagnostics affected = row_count;
      if affected = 0 then
        raise exception 'apply_batch: % % not found or not writable', tbl, row_id;
      end if;

    else
      if (t ->> 'appendOnly')::boolean then
        raise exception 'apply_batch: % is append-only and cannot be deleted', tbl;
      end if;
      execute format('delete from public.%I where id = $1', tbl) using row_id;
      get diagnostics affected = row_count;
      if affected = 0 then
        -- Gone or hidden: a replay. Still visible: RLS refused the delete.
        execute format('select exists (select 1 from public.%I where id = $1)', tbl)
          into found_row using row_id;
        if found_row then
          raise exception 'apply_batch: % % not deletable', tbl, row_id;
        end if;
      end if;
    end if;
  end loop;
end;
$$;

revoke execute on function public.apply_batch(jsonb) from public, anon;
grant execute on function public.apply_batch(jsonb) to authenticated;

-- Whether a client-sent tenant id is this tenant, compared as a uuid (case-insensitive);
-- anything that is not a uuid is not.
create or replace function samesight.is_tenant(value text, tenant uuid)
returns boolean
language sql
immutable
set search_path = ''
as $$
  select value ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
    and value::uuid = tenant;
$$;

revoke execute on function samesight.is_tenant(text, uuid) from public, anon;
grant execute on function samesight.is_tenant(text, uuid) to authenticated;

-- Write path: refused writes, server copy -----------------------------------------------
-- The device keeps and shows its own copy; this one lets the tenant see what failed across
-- the team. Clients can only add to it, with tenant and actor from the token; nothing can
-- update or delete it. The reason fields are what the client reported, not server evidence.
-- Not in the publication, so it never syncs down.

create table if not exists samesight."RejectedWrite" (
  id uuid primary key default gen_random_uuid(),
  "tenantId" uuid not null references public.organizations (id) on delete cascade,
  "actorUserId" uuid,
  "resourceType" text not null,
  "resourceId" text not null,
  "opType" text not null,
  payload jsonb not null,
  "reasonCode" text not null,
  "reasonMessage" text not null,
  "httpStatus" integer not null,
  "createdAt" timestamptz not null default now()
);
create index if not exists "RejectedWrite_tenantId_idx" on samesight."RejectedWrite" ("tenantId", "createdAt");

alter table samesight."RejectedWrite" enable row level security;
revoke all on samesight."RejectedWrite" from public, anon, authenticated;
grant insert on samesight."RejectedWrite" to authenticated;

do $$
declare
  p record;
begin
  for p in select policyname from pg_policies where schemaname = 'samesight' and tablename = 'RejectedWrite' loop
    execute format('drop policy %I on samesight."RejectedWrite"', p.policyname);
  end loop;
end;
$$;

create policy "RejectedWrite: record own" on samesight."RejectedWrite"
  for insert to authenticated
  with check (
    "tenantId" = (select samesight.tenant_id())
    and "actorUserId" = (select auth.uid())
  );

-- rejections: [{table, id, op, data, code, message, status}], at most 100 per call. The
-- payload is kept only when it belongs to the caller's current tenant: a user moved to
-- another tenant may still upload writes queued under the old one, and their content must
-- not become readable by the new tenant. Over 64 kB it is stored as {"truncated": true}.
create or replace function public.record_rejection(rejections jsonb)
returns void
language plpgsql
security invoker
set search_path = ''
as $$
declare
  tenant uuid := (select samesight.tenant_id());
  tenant_cols constant jsonb := '{"project_members": "org_id", "projects": "org_id", "tasks": "org_id"}';
  r jsonb;
  tbl text;
  rid text;
  payload jsonb;
  visible boolean;
begin
  if jsonb_typeof(rejections) is distinct from 'array' then
    raise exception 'record_rejection: rejections must be a JSON array';
  end if;
  if jsonb_array_length(rejections) > 100 then
    raise exception 'record_rejection: at most 100 rejections per call';
  end if;
  if tenant is null then
    raise exception 'record_rejection: the token carries no tenant' using errcode = '28000';
  end if;
  for r in select value from jsonb_array_elements(rejections) loop
    tbl := r ->> 'table';
    rid := r ->> 'id';
    payload := coalesce(r -> 'data', '{}'::jsonb);
    if jsonb_typeof(payload) <> 'object' then
      payload := '{}'::jsonb;
    end if;
    if tenant_cols ? tbl and payload ? (tenant_cols ->> tbl) then
      -- A PUT carries its tenant.
      if not samesight.is_tenant(payload ->> (tenant_cols ->> tbl), tenant) then
        payload := '{"redacted": "another tenant"}'::jsonb;
      end if;
    else
      -- A PATCH or DELETE does not: keep it only if the row is one the caller can see now.
      visible := false;
      if tenant_cols ? tbl and rid ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then
        execute format('select exists (select 1 from public.%I where id = $1)', tbl)
          into visible using rid::uuid;
      end if;
      if not visible then
        payload := '{"redacted": "not visible to this tenant"}'::jsonb;
      end if;
    end if;
    if pg_column_size(payload) > 65536 then
      payload := '{"truncated": true}'::jsonb;
    end if;
    insert into samesight."RejectedWrite"
      ("tenantId", "actorUserId", "resourceType", "resourceId", "opType", payload,
       "reasonCode", "reasonMessage", "httpStatus")
    values (
      tenant,
      (select auth.uid()),
      left(coalesce(tbl, ''), 200),
      left(coalesce(rid, ''), 200),
      left(coalesce(r ->> 'op', ''), 20),
      payload,
      left(coalesce(r ->> 'code', 'UNKNOWN'), 100),
      left(coalesce(r ->> 'message', ''), 2000),
      case when jsonb_typeof(r -> 'status') = 'number' then (r ->> 'status')::numeric::integer else 0 end
    );
  end loop;
end;
$$;

revoke execute on function public.record_rejection(jsonb) from public, anon;
grant execute on function public.record_rejection(jsonb) to authenticated;
